public async Task<IActionResult> Get(int id, CancellationToken ct)
{
    var product = await _db.Products.FirstOrDefaultAsync(p => p.Id == id, ct);
    if (product == null) return NotFound();

    var reviews = await _httpClient.GetFromJsonAsync<List<Review>>(
        $"https://reviews.example.com/api/products/{id}", ct);

    var result = new ProductDetail(product, reviews);
    return Ok(result);
}

public class QueueProcessor : BackgroundService
{
    private readonly ILogger<QueueProcessor> _logger;

    public QueueProcessor(ILogger<QueueProcessor> logger) => _logger = logger;

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        _logger.LogInformation("Queue processor started");

        while (!stoppingToken.IsCancellationRequested)
        {
            try
            {
                await ProcessNextMessageAsync(stoppingToken);
            }
            catch (OperationCanceledException)
            {
                // Expected during shutdown; exit gracefully
                break;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error processing message");
            }
        }

        _logger.LogInformation("Queue processor stopped");
    }

    private async Task ProcessNextMessageAsync(CancellationToken ct)
    {
        var message = await _queue.ReceiveAsync(ct);
        // Process message...
    }
}
